/* *      QuickDraw III Color Manager *	for GS/VGA Card *	C Interface file *//* Color Conversion *//* Color2Index   Finds the best available approximation to a given absolute color,   using a simplified Octree method. Rather than taking the Macintosh   approach of using a giant inverse lookup table, we will instead use   an unweighted Octree to lookup colors. This not only improves memory   usage, but speed of building the lookup table as well*/word Color2Index(rgbColor rgb);/* Grabs the rgb triplet value of the specified color index straight   out of the linear palette */rgbColor Index2Color(word index);/* finds the complement of an absolute color, by applying a 1's complement   to each component in the triplet */rgbColor InvertColor(rgbColor theColor);/* tells whether a given absolute color actually exists in the current   color table. RealColor returns true if the given color exactly matches   an existing palette entry */int RealColor(rgbColor color);/* takes a ColorTable pointed to by myColors, and maps each RGB   value into its nearest available match for the target table.   These best matches are returned in the colorSpec.value fields   of mycolors. Best matches are calculated with Color2Index. */GetSubTable(CTabHandle myColors, CTabHandle targetTbl);